update public.learning_paths
set
  title = 'Information Design / Visual Systems',
  goal = 'Information Design / Visual Systems',
  summary = 'Students learn to transform complex material into visual structures that make relationships, priorities, and actions easier to understand, and to study how people see, group, scan, compare, and misread visual information. The course builds layout, type, and color systems, then charts, maps, diagrams, scalable visual systems, interaction and dashboards, accessibility, research and information architecture, critique, and a polished multi-format information project.',
  data = $infdjson${"slug": "information-design-visual-systems", "title": "Information Design / Visual Systems", "description": "Students learn to transform complex material into visual structures that make relationships, priorities, and actions easier to understand, and to study how people see, group, scan, compare, and misread visual information. The course builds layout, type, and color systems, then charts, maps, diagrams, scalable visual systems, interaction and dashboards, accessibility, research and information architecture, critique, and a polished multi-format information project.", "topics": [{"id": "0a7d5975-c59a-4379-8c88-d1f3f614d53e", "type": "topic", "title": "Information Design Principles and Visual Thinking", "description": "Students learn to transform complex material into visual structures that make relationships, priorities, and actions easier to understand.", "children": [{"id": "ecc3c6a0-6479-40a6-95d1-69d256cc85b3", "type": "subtopic", "title": "Information as a design material", "children": [{"id": "96a54a58-4621-42bd-981a-77b891696e7d", "type": "concept", "title": "Data, content, evidence, instructions, narrative, and decision support"}, {"id": "74345f96-dadc-4eef-8d92-5b65db091e3b", "type": "concept", "title": "Users, tasks, context, constraints, and cognitive load"}, {"id": "0f644302-41fc-4c57-aef2-60153ba34ea5", "type": "concept", "title": "Clarity, density, accuracy, usefulness, and delight"}], "description": "This subtopic treats information as something that can be selected, grouped, sequenced, and shaped."}, {"id": "80b7b543-f222-4a83-85ff-9f91ee7d53c1", "type": "subtopic", "title": "Visual thinking and abstraction", "children": [{"id": "fe69d570-e713-4b70-82bd-17f2f6266fe1", "type": "concept", "title": "Concept maps, affinity clusters, taxonomies, flows, matrices, and hierarchies"}, {"id": "9ecbdca4-929f-4c3f-b8f1-324526079ddf", "type": "concept", "title": "Abstraction, simplification, emphasis, contrast, and omission"}, {"id": "bb22ea27-cb89-4bc5-9216-5a48e57efc53", "type": "concept", "title": "Sketching, paper prototypes, thumbnails, and critique-ready studies"}], "description": "Students learn how sketching, grouping, and abstraction reveal structure before styling begins."}, {"id": "9160d79c-bd8e-4c60-a1f5-2e27f08179f8", "type": "subtopic", "title": "Design intent and audience fit", "children": [{"id": "33f9aeab-13fe-4de9-a0fa-edb1cda8fd7c", "type": "concept", "title": "Audience goals, domain literacy, accessibility needs, and use environment"}, {"id": "b65da961-98b7-4a46-8911-71f164eeb2a1", "type": "concept", "title": "Information goals: explain, compare, locate, persuade, instruct, or explore"}, {"id": "1a80d498-0b38-41dc-998e-b812fbe60875", "type": "concept", "title": "Success criteria, usability criteria, and design rationale"}], "description": "This section connects visual decisions to what the audience needs to know, compare, remember, or do."}]}, {"id": "ef37f7aa-76c2-4b39-8841-43619f99c253", "type": "topic", "title": "Visual Perception, Cognition, and Meaning", "description": "Students study how people see, group, scan, compare, and misread visual information.", "children": [{"id": "68537069-20ac-4ee6-b06f-318fb647e7db", "type": "subtopic", "title": "Gestalt and visual grouping", "children": [{"id": "b73ba137-67f8-4034-a170-58bcaf7c0760", "type": "concept", "title": "Proximity, similarity, continuity, closure, common region, and figure-ground"}, {"id": "d000280d-9ee3-454a-8c33-08f98f76f432", "type": "concept", "title": "Grouping, chunking, scanning, salience, and visual search"}, {"id": "6ff6b2a1-c002-4e9c-9964-19612069175b", "type": "concept", "title": "When visual grouping helps and when it creates false relationships"}], "description": "This subtopic explains why proximity, similarity, continuity, enclosure, and figure-ground relationships guide interpretation."}, {"id": "01c5c465-a216-4f2c-9a1e-dc5642512cb3", "type": "subtopic", "title": "Cognitive load and attention", "children": [{"id": "b6b62139-b61e-46d5-8192-02fae1899060", "type": "concept", "title": "Working memory, preattentive features, annotation, sequencing, and progressive disclosure"}, {"id": "55e9f6fc-ba61-4c7d-92eb-1106934b17bd", "type": "concept", "title": "Signal, noise, clutter, redundancy, and visual hierarchy"}, {"id": "6a9a4a16-f439-4e50-9c1e-52038942877e", "type": "concept", "title": "Designing for quick scan, deep read, and repeated use"}], "description": "Students learn to manage complexity without flattening important nuance."}, {"id": "dbeddf46-a3d7-41f5-bec7-e3a973d3e12b", "type": "subtopic", "title": "Visual rhetoric and interpretation", "children": [{"id": "ef6e83a1-2565-4803-87bc-814642deed34", "type": "concept", "title": "Framing, metaphor, emphasis, omission, and implied causality"}, {"id": "690c7ac1-f23d-4c36-b3bc-d09a6cdb7e92", "type": "concept", "title": "Trust, authority, ambiguity, and emotional tone"}, {"id": "10bb6f50-67be-4e9e-8f5c-930aee053dbc", "type": "concept", "title": "Ethical implications of visual simplification"}], "description": "This section shows how visual systems persuade, frame, and imply values."}]}, {"id": "7e1fb233-78ab-4397-a403-dbca6d3f1c1a", "type": "topic", "title": "Hierarchy, Grids, Layout, and Composition Systems", "description": "Students build durable layout systems that organize complex information across print, screen, and environmental formats.", "children": [{"id": "50a4246e-53e6-49a8-b2d5-acb22a46bea6", "type": "subtopic", "title": "Hierarchy and reading paths", "children": [{"id": "fcb81079-24e1-4920-97f3-4fdebdb7d56c", "type": "concept", "title": "Scale, weight, color, position, spacing, alignment, and contrast"}, {"id": "be9ea57f-88a9-4ef7-8efb-ff69201252fc", "type": "concept", "title": "Headers, labels, captions, legends, annotations, and metadata"}, {"id": "2459ed0c-a0da-4860-a854-11a7af63ffec", "type": "concept", "title": "Skimmability, wayfinding within a page, and layered detail"}], "description": "This subtopic teaches students to control what is seen first, second, and last."}, {"id": "8fa1e1a5-710c-4be6-9e5b-db0fd754c9fb", "type": "subtopic", "title": "Grid systems and modular layouts", "children": [{"id": "e31e24b6-4d06-4f37-bfd2-1b7cb61f0827", "type": "concept", "title": "Columns, modules, baselines, margins, gutters, cards, panels, and responsive grids"}, {"id": "98328431-a460-4fe7-8529-ff3f44a199a7", "type": "concept", "title": "Editorial grids, dashboard grids, poster systems, and environmental panels"}, {"id": "20b7fe4d-2541-4893-aa39-1ed4042d6db6", "type": "concept", "title": "Rules, exceptions, and when a grid should bend"}], "description": "Students learn to make layout decisions repeatable and adaptable."}, {"id": "cdf4adce-ea3d-4214-8676-761fb1c95259", "type": "subtopic", "title": "Composition across formats", "children": [{"id": "b4a44625-ebbb-421e-9190-35e4622ddbd0", "type": "concept", "title": "Print, mobile, desktop, presentation, social, signage, and exhibition formats"}, {"id": "803b9fa1-a2e2-414e-8316-97cf8c53841d", "type": "concept", "title": "Responsive reflow, aspect ratios, breakpoints, and hierarchy preservation"}, {"id": "62af1bf9-e50a-4f31-9b23-40c0396a9d35", "type": "concept", "title": "Systematic variation rather than one-off layouts"}], "description": "This section asks students to preserve coherence across different media and sizes."}]}, {"id": "32e0dbcb-d5c4-4513-b312-9b547d1786e0", "type": "topic", "title": "Typography for Information and Complex Reading", "description": "Students learn to use type as a system for hierarchy, tone, legibility, navigation, and dense information.", "children": [{"id": "60c421e6-223e-46e8-9250-1ea697e08a7f", "type": "subtopic", "title": "Type choice and typographic voice", "children": [{"id": "498acff5-6ef4-4ee3-98d7-55103bc726b8", "type": "concept", "title": "Serif, sans serif, slab, mono, variable, display, text, and UI type"}, {"id": "8192f575-cf52-457e-9d39-93d6f53e5c6c", "type": "concept", "title": "Tone, authority, neutrality, warmth, urgency, and brand fit"}, {"id": "eb6b5cb2-b2d3-41f3-a46a-c179811012d1", "type": "concept", "title": "Pairing, contrast, type families, and typographic restraint"}], "description": "This subtopic connects typeface selection to audience, subject, medium, and credibility."}, {"id": "ec47e5d9-2f59-4375-8cae-ac7a8c62f22f", "type": "subtopic", "title": "Legibility and readability", "children": [{"id": "4b3b65f7-a0c9-4dd0-965e-4668fcfd588c", "type": "concept", "title": "Size, leading, measure, tracking, kerning, line breaks, paragraph spacing, and alignment"}, {"id": "dd734e8c-5a83-4310-8f44-52c6f7f85c98", "type": "concept", "title": "Screen readability, small sizes, tables, captions, labels, and legends"}, {"id": "b0c53a40-3bd3-49fc-95a6-2dff4342a72d", "type": "concept", "title": "Accessibility, dyslexia-aware choices, contrast, and language support"}], "description": "Students refine the details that make complex information usable."}, {"id": "304dcfcb-9767-4001-a30b-138e19db8269", "type": "subtopic", "title": "Typographic systems", "children": [{"id": "4f475148-9e64-411e-95a8-ce1ef9e62a7f", "type": "concept", "title": "Type scales, heading ladders, labels, sidebars, callouts, captions, and footnotes"}, {"id": "5a2311ed-8252-4bdc-b41f-8c6874ef121f", "type": "concept", "title": "Editorial systems, dashboard labels, wayfinding typography, and responsive type"}, {"id": "9b1dd3ed-d5de-4150-ae8b-f3e669e959cd", "type": "concept", "title": "Documentation of typographic rules and exceptions"}], "description": "This section turns type decisions into reusable rules for multi-part artifacts."}]}, {"id": "fb3f0daa-266a-4951-9dde-d154e636bbd3", "type": "topic", "title": "Color, Contrast, and Information Encoding", "description": "Students use color to organize, encode, differentiate, and guide attention without sacrificing accessibility or truthfulness.", "children": [{"id": "f7a384fa-b459-41ea-91d3-406a822d4c0d", "type": "subtopic", "title": "Color as structure", "children": [{"id": "77a4de4d-0d59-4d7e-a400-1c5d45a6f2a9", "type": "concept", "title": "Categorical, sequential, diverging, alert, status, and brand color systems"}, {"id": "16fa4da0-e218-48d8-83c1-f8b2f1d91669", "type": "concept", "title": "Hue, value, saturation, temperature, contrast, and hierarchy"}, {"id": "0ec46ea4-6156-4fda-a033-7f5e135121b2", "type": "concept", "title": "Color consistency across charts, maps, icons, and interfaces"}], "description": "This subtopic teaches color as a functional layer, not decoration."}, {"id": "8abf0011-7d39-41f6-aa66-1d46f2cee46c", "type": "subtopic", "title": "Accessibility and perception", "children": [{"id": "bbe9c0af-6529-4d40-8716-b47d19c8ffb7", "type": "concept", "title": "Contrast ratios, color vision deficiency, grayscale checks, dark mode, and print conversion"}, {"id": "42ad23f5-1866-4279-918c-e115cbefab6d", "type": "concept", "title": "Redundant encodings with labels, texture, shape, position, or annotation"}, {"id": "9dfd0aea-2402-4351-a533-8a3190e84ab0", "type": "concept", "title": "Testing palettes for legibility, meaning, and cultural assumptions"}], "description": "Students learn to design for varied visual abilities and contexts."}, {"id": "4a901902-0907-4d21-a1b2-1c65c803ce9f", "type": "subtopic", "title": "Ethics of color and emphasis", "children": [{"id": "570ad0c8-ffb6-455d-9a18-a855e9f456d7", "type": "concept", "title": "Misleading alert colors, rainbow scales, false precision, and emotional manipulation"}, {"id": "56964a78-6e97-46a8-b9fd-b4f67966e8b0", "type": "concept", "title": "Uncertainty, risk, priority, and severity color choices"}, {"id": "3068a92d-33a5-4e3a-a96d-4d0715dfd78d", "type": "concept", "title": "Documentation of color meaning and appropriate use"}], "description": "This section examines how color can exaggerate, hide, or distort information."}]}, {"id": "0070ac45-0b5a-4dfc-a124-b480e6880ab5", "type": "topic", "title": "Data Visualization: Charts, Integrity, and Story", "description": "Students learn to choose, build, critique, and annotate charts that communicate data accurately and clearly.", "children": [{"id": "69680f1a-cc6d-40c7-9ab4-095d5fdf429e", "type": "subtopic", "title": "Chart selection", "children": [{"id": "be1d1486-ead4-4da0-8ed3-ccc763eea15f", "type": "concept", "title": "Comparison, change over time, distribution, relationship, part-to-whole, ranking, and uncertainty"}, {"id": "66815268-4f23-4a52-94d0-fd6fcfb41dd0", "type": "concept", "title": "Bar, line, scatter, histogram, slope, dot, heatmap, small multiples, and table-chart hybrids"}, {"id": "d4a6ba8f-7301-45f2-9b5a-857cf71cae0b", "type": "concept", "title": "When not to visualize and when a table is better"}], "description": "This subtopic ties visual form to analytical purpose."}, {"id": "4e7b8650-796f-4fa4-ae8f-364363401de4", "type": "subtopic", "title": "Data integrity and misleading charts", "children": [{"id": "fc9af8b2-b6c0-425b-ad33-c029103fa93b", "type": "concept", "title": "Baselines, scales, axes, binning, aggregation, outliers, sampling, and missing data"}, {"id": "8b9c5bea-e527-4e1e-a1b7-a85d12f5ac8b", "type": "concept", "title": "Cherry-picking, truncated axes, dual axes, decorative distortion, and false causality"}, {"id": "069dc82e-4e16-426a-ad3e-59d335895181", "type": "concept", "title": "Source notes, methodology notes, and uncertainty notes"}], "description": "Students learn to spot and avoid visual distortion."}, {"id": "410f7783-a6c6-455b-b2d1-8e68fdd49ee7", "type": "subtopic", "title": "Data storytelling and annotation", "children": [{"id": "e08c55e0-3946-457e-956d-e92f5363943e", "type": "concept", "title": "Titles, subtitles, labels, callouts, captions, source lines, and narrative sequence"}, {"id": "ff0fcdbb-14f6-47f1-949f-f041873bbcca", "type": "concept", "title": "Audience context, key takeaway, explanatory flow, and chart-to-chart transitions"}, {"id": "5b48cca9-7fdb-4be0-971a-d2235d065d0c", "type": "concept", "title": "Editorial judgment, caveats, and actionable insight"}], "description": "This section teaches students to guide interpretation without oversimplifying."}]}, {"id": "76d69dcd-3346-4875-aa11-a01cceeea282", "type": "topic", "title": "Maps, Spatial Information, and Wayfinding", "description": "Students design spatial systems that help people locate, navigate, compare, and understand place-based information.", "children": [{"id": "518fc833-48c5-4980-85e8-a6a87bfd3a6c", "type": "subtopic", "title": "Map design and spatial data", "children": [{"id": "c4a60b3b-705c-4f6b-9c32-2a8e1429b3a4", "type": "concept", "title": "Projection, scale, boundary, layers, symbols, labels, legends, and basemaps"}, {"id": "3ae2fac1-9107-4ad0-9a24-b53cae053e02", "type": "concept", "title": "Choropleth, proportional symbol, dot density, flow, route, and locator maps"}, {"id": "4be59fef-b0d8-4d6d-9dcb-f3edaf347e66", "type": "concept", "title": "Geographic bias, normalization, modifiable area units, and map ethics"}], "description": "This subtopic introduces maps as arguments about space, scale, and relevance."}, {"id": "02054f61-01e1-4930-bbde-5922b78da26e", "type": "subtopic", "title": "Wayfinding systems", "children": [{"id": "d223bed2-ec25-4f12-8b46-425b22996169", "type": "concept", "title": "User journeys, decision points, paths, nodes, landmarks, districts, and signage hierarchy"}, {"id": "94714e87-95d7-4f2e-9657-0acae9102591", "type": "concept", "title": "Pictograms, arrows, color zones, destination naming, and environmental constraints"}, {"id": "124b5a3f-a6e2-459b-9558-d5e65aa8f902", "type": "concept", "title": "Accessibility, multilingual systems, emergency information, and maintenance"}], "description": "Students learn how signage, naming, landmarks, and sequence support navigation."}, {"id": "379a9e3f-5b5c-41a7-8cab-d81563ebfc23", "type": "subtopic", "title": "Spatial storytelling", "children": [{"id": "7d87605f-13a9-4bdd-bc5c-1c65802d3cbf", "type": "concept", "title": "Story maps, routes, timelines, overlays, before/after views, and annotated spatial evidence"}, {"id": "a4f862d1-ebbf-4b1b-8804-e3af48a15486", "type": "concept", "title": "Place, memory, politics, infrastructure, risk, and public communication"}, {"id": "af05cabc-0590-4c45-be3e-de11d8c4760f", "type": "concept", "title": "Print, mobile, kiosk, exhibit, and outdoor use cases"}], "description": "This section links maps and journeys to narrative and explanation."}]}, {"id": "23192477-3633-454c-8bef-792e91b30452", "type": "topic", "title": "Diagrams, Infographics, Icons, and Symbol Systems", "description": "Students develop visual languages for explaining processes, relationships, instructions, and abstract concepts.", "children": [{"id": "f8f2ea4c-850e-4ed8-9970-36d8f90e9e03", "type": "subtopic", "title": "Diagram types and logic", "children": [{"id": "77a5521a-37b8-414a-b44f-867038341978", "type": "concept", "title": "Flowcharts, process diagrams, system maps, decision trees, timelines, matrices, and exploded views"}, {"id": "5f03f118-2b42-4787-87e1-2577bc7f5e99", "type": "concept", "title": "Causality, sequence, dependency, hierarchy, feedback, and lifecycle"}, {"id": "25f7a375-2fca-49a6-b103-7f3bc2088c92", "type": "concept", "title": "Labels, legends, arrows, connectors, nesting, and directionality"}], "description": "This subtopic gives students a toolkit for visualizing non-quantitative complexity."}, {"id": "39d05ad0-c069-4b07-af12-6c477b42520e", "type": "subtopic", "title": "Infographic structure", "children": [{"id": "7d17ca75-f631-43af-b858-8d5f801f348d", "type": "concept", "title": "Editorial framing, sections, modules, visual hooks, facts, sources, and annotation"}, {"id": "35766e66-d2bd-4923-a0ab-a69053e1f7d2", "type": "concept", "title": "Balancing illustration, charts, text, and white space"}, {"id": "3dfdb693-c936-435d-9f4b-af7807ff58d3", "type": "concept", "title": "Avoiding poster clutter, novelty charts, and unsupported claims"}], "description": "Students learn to combine data, explanation, image, and narrative in a coherent artifact."}, {"id": "1b007af9-441e-4198-b5ad-3ec2ec917035", "type": "subtopic", "title": "Icons and symbols", "children": [{"id": "91b8a6d0-c329-4167-ba09-728fc156ca81", "type": "concept", "title": "Pictograms, glyphs, line style, fill style, stroke weight, metaphor, and recognition"}, {"id": "15df48d5-662d-438a-ba34-913caf59822b", "type": "concept", "title": "Icon grids, optical correction, families, variants, and naming"}, {"id": "07974d04-a54d-45d1-aaae-82cca967927f", "type": "concept", "title": "Cultural interpretation, accessibility, ambiguity, and symbol testing"}], "description": "This section develops systematic icon design for clarity and reuse."}]}, {"id": "beeee4bf-a69d-4e67-bd6b-57f6078416e4", "type": "topic", "title": "Visual Systems, Design Systems, and Multi-Platform Consistency", "description": "Students build rules, components, and patterns that can scale across many artifacts without becoming rigid.", "children": [{"id": "eb11eed5-7ca0-498c-a66d-8e4e0cd3435b", "type": "subtopic", "title": "System elements", "children": [{"id": "1b73fce1-3371-4437-a520-0a1759e2328c", "type": "concept", "title": "Typography, color, grids, spacing, icons, imagery, charts, maps, components, and motion rules"}, {"id": "c2967ff2-98e2-4c53-a19b-180f70dfdebf", "type": "concept", "title": "Tokens, components, templates, examples, and anti-examples"}, {"id": "6e5fe297-83dd-49d1-ab47-6fd27043f75c", "type": "concept", "title": "Consistency, flexibility, and governance"}], "description": "This subtopic identifies the building blocks of a visual system."}, {"id": "1821d796-2044-44bc-bca0-590c9a0b34b3", "type": "subtopic", "title": "Design systems for information", "children": [{"id": "3a01aa89-6fae-49a7-a71e-21d5698fafe4", "type": "concept", "title": "Style guides, component libraries, pattern libraries, Figma files, and content rules"}, {"id": "4a4f3914-099a-44bf-bee6-b41cc23c0070", "type": "concept", "title": "Chart libraries, map styles, table styles, annotation rules, and accessibility rules"}, {"id": "9c4f62d2-88d5-4ec5-a57f-e8fae1616f93", "type": "concept", "title": "Versioning, maintenance, quality control, and review workflows"}], "description": "Students learn to document decisions so others can use and extend the system."}, {"id": "7173ec8d-2a74-4c2a-9baa-015dd7be6988", "type": "subtopic", "title": "Cross-platform adaptation", "children": [{"id": "320957e9-9eb7-4f06-a7d1-c764245e7731", "type": "concept", "title": "Responsive systems, editorial series, campaign systems, dashboards, and signage families"}, {"id": "ed2d1c2b-2ac9-44fa-882b-494a8b1635f1", "type": "concept", "title": "Platform constraints, content priority, interaction depth, and update cycles"}, {"id": "5b83ad5f-21a1-49e6-b301-7884c71737e1", "type": "concept", "title": "Testing the same system across multiple realistic deliverables"}], "description": "This section focuses on preserving meaning across print, screen, presentation, and environment."}]}, {"id": "799e4241-7656-4a16-ac01-fa8b249872cc", "type": "topic", "title": "Interaction, Dashboards, and Exploratory Information Design", "description": "Students learn how interaction changes information design from a fixed message to an exploratory tool.", "children": [{"id": "18ffe6de-1b0a-471e-81e0-d40aecb12131", "type": "subtopic", "title": "Interactive visualization basics", "children": [{"id": "c43a7741-e64b-4967-b8f4-c67d788ffee5", "type": "concept", "title": "Hover, filter, sort, search, zoom, pan, drill-down, tooltip, and linked views"}, {"id": "e4821501-6eaa-4589-ab5a-5f7c59084376", "type": "concept", "title": "Overview-detail, progressive disclosure, small multiples, and guided exploration"}, {"id": "a2e91a7f-7eac-4471-b614-2fce5ce25958", "type": "concept", "title": "Affordances, feedback, empty states, loading states, and error states"}], "description": "This subtopic introduces interaction as a way to reveal detail and support exploration."}, {"id": "39987019-8a46-4b20-9de9-24602b9c38f7", "type": "subtopic", "title": "Dashboard design", "children": [{"id": "8856fe0c-0357-4476-804c-d32cc5b70839", "type": "concept", "title": "KPIs, audience roles, task flows, refresh cadence, filters, layout zones, and alerts"}, {"id": "e346b63d-3816-4d03-a19f-7d1df35a0306", "type": "concept", "title": "Executive, analytical, operational, public, and explanatory dashboards"}, {"id": "f7903004-12e7-4119-9b01-6f12f535c291", "type": "concept", "title": "Avoiding vanity metrics, overloaded screens, and weak information scent"}], "description": "Students learn to build dashboards around decisions, not just metrics."}, {"id": "744c6af6-5984-4768-83e0-79564112840d", "type": "subtopic", "title": "Prototyping and testing", "children": [{"id": "fbf7de76-7b42-4c91-ba11-b63ff082fd9e", "type": "concept", "title": "Wireframes, clickable prototypes, data prototypes, usability tests, and critique prompts"}, {"id": "6f6ceac5-0b40-4df6-813c-6dc2233f5b4f", "type": "concept", "title": "Task success, comprehension, trust, time-to-answer, and error discovery"}, {"id": "6eab6040-012e-42cc-8e96-c96c23cfe815", "type": "concept", "title": "Iterating based on evidence rather than taste alone"}], "description": "This section adds human-centered iteration to visual systems."}]}, {"id": "61f22a75-ec90-4851-b282-1818d681e622", "type": "topic", "title": "Accessibility, Universal Design, and Inclusive Communication", "description": "Students design information for varied abilities, languages, devices, environments, and levels of domain expertise.", "children": [{"id": "6023fea7-3b8f-45f3-b822-904f7ed88f35", "type": "subtopic", "title": "Accessibility foundations", "children": [{"id": "432148e3-9840-4121-9ab8-82a7b607534f", "type": "concept", "title": "Contrast, type size, alt text, captions, keyboard use, focus order, semantic structure, and screen readers"}, {"id": "d893e48b-5814-4e2c-a413-cbbc052673c1", "type": "concept", "title": "Color-independent meaning, plain language, cognitive accessibility, and touch target size"}, {"id": "be4d869f-a8b4-496d-8a13-14d03697005e", "type": "concept", "title": "WCAG thinking, W3C resources, and accessibility checks"}], "description": "This subtopic covers baseline practices for readable, usable visual communication."}, {"id": "e057bff5-0fb2-4a91-9da2-853ae24b8ce1", "type": "subtopic", "title": "Inclusive audiences", "children": [{"id": "45271b43-f89f-4588-a028-0071350cf587", "type": "concept", "title": "Language access, translation, cultural context, disability, age, literacy, numeracy, and device constraints"}, {"id": "94d3c44e-bf4a-4eb8-a20f-46974ab4dc46", "type": "concept", "title": "Public information, health information, civic information, wayfinding, and crisis communication"}, {"id": "8f434094-63c3-4e6c-a53d-cc89d15d0f71", "type": "concept", "title": "Participatory critique, community review, and respectful representation"}], "description": "Students learn to design beyond a default user."}, {"id": "af1a73fe-68da-411b-8c80-5a8914b04d34", "type": "subtopic", "title": "Ethics and harm reduction", "children": [{"id": "46d2d656-ad66-4f7a-bd28-233f1a773bc3", "type": "concept", "title": "Privacy, sensitive data, stigmatizing labels, surveillance, risk maps, and deficit framing"}, {"id": "56f9a901-6a85-42b8-be7f-275413e3db05", "type": "concept", "title": "Responsible simplification, uncertainty, consent, and community impact"}, {"id": "62d45ac7-58f7-4faf-8eff-e07fe578bd69", "type": "concept", "title": "Documentation of ethical choices and tradeoffs"}], "description": "This section asks how design choices can include, exclude, clarify, or mislead."}]}, {"id": "b74c99d5-ea43-427f-8359-988bf6b07029", "type": "topic", "title": "Research, Content Strategy, and Information Architecture", "description": "Students learn to gather, structure, edit, and prioritize content before designing visual form.", "children": [{"id": "d9d5de36-d2b1-4185-82e0-9a548879e216", "type": "subtopic", "title": "Design research", "